import React, { useState, useEffect } from 'react';
import { Canvas } from '@react-three/fiber';
import { OrbitControls } from '@react-three/drei';
import { OBJLoader } from 'three/examples/jsm/loaders/OBJLoader';
import * as THREE from 'three';

// Register geometry explicitly
import { BoxBufferGeometry } from 'three';

const ModelLoader = ({ modelPath }) => {
  const [model, setModel] = useState(null);

  useEffect(() => {
    const loader = new OBJLoader();

    loader.load(
      modelPath,
      (obj) => {
        // When the model is loaded, store it in the state
        setModel(obj);
      },
      undefined, // onProgress callback (optional)
      (error) => {
        console.error('Error loading OBJ:', error);
      }
    );
  }, [modelPath]);

  return model ? <primitive object={model} /> : <mesh><boxBufferGeometry args={[1, 1, 1]} /><meshStandardMaterial color="gray" /></mesh>;
};

const App = () => {
  // Toggle for switching between ASCII and OBJ
  const [useAscii, setUseAscii] = useState(false);

  // Path to the OBJ model (this could be dynamically set if needed)
  const modelPath = '/stls/model1.obj'; // Assuming the OBJ file is in the `stls` folder

  return (
    <div>
      <h1>3D Model Viewer</h1>

      {/* Button to toggle between ASCII or OBJ view */}
      <button onClick={() => setUseAscii(!useAscii)}>
        {useAscii ? 'Use OBJ' : 'Use ASCII'}
      </button>

      <Canvas camera={{ position: [0, 0, 5], fov: 75 }}>
        <ambientLight intensity={0.5} />
        <spotLight position={[10, 10, 10]} intensity={1} />
        <OrbitControls />

        {/* Load and display model */}
        {!useAscii ? (
          <ModelLoader modelPath={modelPath} />
        ) : (
          // Placeholder for ASCII rendering (could be implemented separately)
          <mesh>
            <BoxBufferGeometry args={[1, 1, 1]} />
            <meshStandardMaterial color="gray" />
          </mesh>
        )}
      </Canvas>
    </div>
  );
};

export default App;
